g effort (thinking level, intelligence)","input":{"hint":"[level]"},"subcommands":[{"name":"off","description":"No reasoning"},{"name":"minimal","description":"Very brief reasoning (~1k tokens)"},{"name":"low","description":"Light reasoning (~2k tokens)"},{"name":"medium","description":"Moderate reasoning (~8k tokens)"},{"name":"high","description":"Deep reasoning (~16k tokens)"},{"name":"xhigh","description":"Extended reasoning (~32k tokens)"},{"name":"max","description":"Maximum reasoning the model supports"},{"name":"auto","description":"Auto-detect per prompt"}],"source":"builtin"},{"name":"advisor","description":"Toggle advisor","input":{"hint":"[on|off|status|dump [raw]|configure]"},"subcommands":[{"name":"on","description":"Enable the advisor"},{"name":"off","description":"Disable the advisor"},{"name":"status","description":"Show advisor status"},{"name":"dump","description":"Copy the advisor's transcript to clipboard","usage":"[raw]"},{"name":"configure","description":"Open the advisor configuration editor (TUI)"}],"source":"builtin"},{"name":"export","description":"Export session to HTML file","input":{"hint":"[--themes] [path]"},"source":"builtin"},{"name":"trace","description":"Open this session's trace in the stats dashboard","source":"builtin"},{"name":"dump","description":"Return full transcript as plain text, with LLM request JSON path","input":{"hint":"[all|anon]"},"subcommands":[{"name":"all","description":"Write a zip with the main transcript, LLM request JSON, and one file per subagent"},{"name":"anon","description":"Write a zip of anonymized session JSONL (contents redacted, metadata kept) plus subagents"}],"source":"builtin"},{"name":"share","description":"Share session via an encrypted link (share server or secret gist)","source":"builtin"},{"name":"browser","description":"Toggle browser eval-prelude headless vs visible mode","input":{"hint":"[headless|visible]"},"subcommands":[{"name":"headless","description":"Switch to headless mode"},{"name